#!/usr/bin/env bash
# Print up to three client IPs, ordered by request count and then first sighting.
awk '
NF {
    ip = $1
    if (!(ip in count))
        first[ip] = NR
    count[ip]++
}
END {
    for (rank = 1; rank <= 3; rank++) {
        best = ""
        for (ip in count) {
            if (ip in chosen)
                continue
            if (best == "" || count[ip] > count[best] || \
                (count[ip] == count[best] && first[ip] < first[best]))
                best = ip
        }
        if (best == "")
            break
        print best
        chosen[best] = 1
    }
}
' access.log
